package in.otrail;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.util.AtomicFile;
import android.widget.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;
import org.json.*;

/** Approved reconstructed journeys are separate from measured GPS and can be independently hidden. */
final class HistoricalTrails implements AutoCloseable {
 static final int PICK=82;
 record Entry(String id,String title,String raw,String uri,boolean visible,long created,double meters,List<RoutePlan.Point> points,JSONArray waypoints){}
 private final Activity activity;private final Runnable changed;private final Consumer<List<RoutePlan.Point>> preview;
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private volatile List<Entry> entries=List.of(),drafts=List.of();private volatile boolean closed,busy,loadError;
 private final AtomicFile file;
 HistoricalTrails(Activity a,Runnable changed,Consumer<List<RoutePlan.Point>> preview){activity=a;this.changed=changed;this.preview=preview;file=new AtomicFile(new File(a.getFilesDir(),"historical-trails-v1.json"));worker.execute(()->{try{if(file.getBaseFile().exists()){JSONObject saved=new JSONObject(read(file.openRead(),24000000));JSONArray rows=saved.getJSONArray("trails");List<Entry> found=new ArrayList<>();for(int i=0;i<rows.length();i++)found.add(decode(rows.getJSONObject(i)));entries=List.copyOf(found);}post(changed);}catch(Exception e){loadError=true;post(()->message("Cannot read historical trails",e.getMessage()));}});}
 List<Entry> entries(){return entries;}List<Entry> drafts(){return drafts;}
 double totalMeters(){double sum=0;for(Entry e:entries)sum+=e.meters();return sum;}
 private void post(Runnable r){activity.runOnUiThread(()->{if(!closed&&!activity.isDestroyed())r.run();});}
 private void message(String title,String text){new AppDialogs(activity).setTitle(title).setMessage(text).setPositiveButton("Close",null).show();}
 void show(){
  List<String> names=new ArrayList<>(List.of("＋ Add comma-separated list","＋ Import files","Review pending previews ("+drafts.size()+")"));
  for(Entry e:entries)names.add((e.visible()?"● Loaded · ":"○ Unloaded · ")+e.title()+String.format(Locale.US," · %.1f km",e.meters()/1000));
  new AppDialogs(activity).setTitle("Historical trails · bright yellow").setItems(names.toArray(new String[0]),(d,index)->{if(index==0)edit(null,"Historic journey","","");else if(index==1){Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);activity.startActivityForResult(pick,PICK);}else if(index==2)review();else options(entries.get(index-3));}).setNegativeButton("Close",null).show();
 }
 private void options(Entry entry){new AppDialogs(activity).setTitle(entry.title()).setItems(new String[]{entry.visible()?"Unload from map":"Load on map","Edit list / chronology","Reload source file","Remove merged journey"},(d,index)->{
  if(index==0)saveReplacement(new Entry(entry.id(),entry.title(),entry.raw(),entry.uri(),!entry.visible(),entry.created(),entry.meters(),entry.points(),entry.waypoints()));
  else if(index==1)edit(entry.id(),entry.title(),entry.raw(),entry.uri());
  else if(index==2){if(entry.uri().isBlank())edit(entry.id(),entry.title(),entry.raw(),"");else stage(List.of(new Source(entry.id(),entry.title(),null,entry.uri())));}
  else new AppDialogs(activity).setTitle("Remove "+entry.title()+"?").setMessage("Removes this reconstructed journey and its distance from Total. Recorded GPS stays intact.").setPositiveButton("Remove",(x,w)->worker.execute(()->{try{List<Entry> next=new ArrayList<>(entries);next.removeIf(e->e.id().equals(entry.id()));persist(next);post(changed);}catch(Exception e){post(()->message("Cannot save",e.getMessage()));}})).setNegativeButton("Cancel",null).show();
 }).setNegativeButton("Close",null).show();}
 private void edit(String id,String title,String raw,String uri){LinearLayout box=new LinearLayout(activity);box.setOrientation(LinearLayout.VERTICAL);EditText name=new EditText(activity);name.setText(title);name.setHint("Journey name");box.addView(name);EditText input=new EditText(activity);input.setText(raw);input.setHint("Delhi, Jaipur, Agra\nOr CSV: order,name,lat,lon,time\nTime: ISO with timezone, YYYY-MM-DD or epoch ms");input.setMinLines(5);input.setMaxLines(10);box.addView(input);AppStyle.nativeTextTree(box);
  AlertDialog dialog=new AppDialogs(activity).setTitle("Build historical road preview").setMessage("List order is chronological unless order/time columns specify it. Cities resolve within India. Review resolved places before approving.").setView(box).setPositiveButton("Build preview",null).setNegativeButton("Cancel",null).create();dialog.show();dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{HistoricTrailInput.parse(input.getText().toString());String label=name.getText().toString().trim();if(label.isBlank())throw new IllegalArgumentException("Name this journey");dialog.dismiss();stage(List.of(new Source(id,label,input.getText().toString(),uri)));}catch(Exception e){input.setError(e.getMessage());}});
 }
 record Source(String id,String title,String raw,String uri){}
 void selected(Intent data){List<Source> sources=new ArrayList<>();List<Uri> uris=new ArrayList<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)uris.add(data.getData());if(uris.size()>20){message("Too many files","Select up to 20 files per batch");return;}for(Uri uri:uris){try{activity.getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}String title="Imported journey";try(android.database.Cursor c=activity.getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())title=c.getString(0);}catch(Exception ignored){}sources.add(new Source(null,title,null,uri.toString()));}stage(sources);}
 private void stage(List<Source> sources){if(busy){message("Building preview","Please wait for the current batch");return;}if(sources.isEmpty())return;busy=true;ProgressDialog progress=AppDialogs.progress(activity);progress.setTitle("Routing historical journeys");progress.setMessage("Resolving places and building road paths…");progress.setCancelable(false);progress.show();worker.execute(()->{List<Entry> built=new ArrayList<>();try{
   for(Source source:sources){String raw=source.raw()!=null?source.raw():read(activity.getContentResolver().openInputStream(Uri.parse(source.uri())),262144);List<HistoricTrailInput.Stop> stops=HistoricTrailInput.parse(raw);List<RoutePlan.Point> points=new ArrayList<>();JSONArray waypoints=new JSONArray();RoutePlan.Point previous=null;double meters=0;
    for(int i=0;i<stops.size();i++){HistoricTrailInput.Stop stop=stops.get(i);int current=i;post(()->progress.setMessage(source.title()+" · place "+(current+1)+" / "+stops.size()));RoutePlan.Point point;String name=stop.name();
     if(stop.lat()!=null){point=new RoutePlan.Point(stop.lat(),stop.lon());if(name.isBlank())name=String.format(Locale.US,"%.4f, %.4f",point.lat(),point.lon());}else{String key=java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(stop.name().toLowerCase(Locale.ROOT).getBytes(StandardCharsets.UTF_8));File cache=new File(activity.getCacheDir(),"historic-place-"+Integer.toHexString(key.hashCode())+".json");if(cache.exists()){JSONObject saved=new JSONObject(read(new FileInputStream(cache),8192));if(!saved.getString("query").equals(stop.name().toLowerCase(Locale.ROOT)))throw new IOException("Place cache mismatch; enter coordinates");point=new RoutePlan.Point(saved.getDouble("lat"),saved.getDouble("lon"));name=saved.getString("name");}else{List<DestinationSearch.Result> found=DestinationSearch.search(activity,stop.name()+", India");if(found.isEmpty())throw new IOException("Place not found: "+stop.name());DestinationSearch.Result chosen=found.get(0);point=chosen.point();name=chosen.name();try(FileOutputStream out=new FileOutputStream(cache)){out.write(new JSONObject().put("query",stop.name().toLowerCase(Locale.ROOT)).put("lat",point.lat()).put("lon",point.lon()).put("name",name).toString().getBytes(StandardCharsets.UTF_8));}}}
     waypoints.put(new JSONObject().put("order",stop.order()).put("name",name).put("lat",point.lat()).put("lon",point.lon()).put("time",stop.time()==null?JSONObject.NULL:stop.time()));
     if(previous!=null){String engine=OfflineRouting.engine(activity),json=null;Exception failure=null;if(!engine.equals("online"))try{json=OfflineRouting.route(activity,engine,previous,point);}catch(Exception e){failure=e;}else json=OnlineRouting.route(NavigationManager.get(activity).server(),previous,point);
      if(json==null)throw new IOException("Offline road routing failed; download matching graph tiles or select online routing. "+(failure==null?"":failure.getMessage()));RoutePlan route=OsrmRouteParser.parse(json);if(RoutePlan.metres(previous,route.points.get(0))>1500||RoutePlan.metres(point,route.points.get(route.points.size()-1))>1500)throw new IOException("Road path is too far from a chosen place; use more precise coordinates");meters+=route.distance;for(int n=points.isEmpty()?0:1;n<route.points.size();n++)points.add(route.points.get(n));if(points.size()>200000)throw new IOException("Journey too detailed; split it into smaller files");}
     previous=point;
    }
    built.add(new Entry(source.id()==null?UUID.randomUUID().toString():source.id(),source.title(),raw,source.uri(),true,System.currentTimeMillis(),meters,List.copyOf(points),waypoints));
   }
   post(()->{List<Entry> next=new ArrayList<>(drafts);for(Entry e:built){next.removeIf(old->old.id().equals(e.id()));next.add(e);}drafts=List.copyOf(next);changed.run();review();});
  }catch(Exception e){post(()->message("Preview failed · existing trails retained",e.getMessage()));}finally{busy=false;post(progress::dismiss);}});}
 private void review(){if(drafts.isEmpty()){message("No pending previews","Add a list or import files first.");return;}List<Entry> batch=List.copyOf(drafts);StringBuilder text=new StringBuilder();double total=0;for(Entry e:batch){total+=e.meters();text.append(e.title()).append(String.format(Locale.US," · %.1f km\n",e.meters()/1000));for(int i=0;i<e.waypoints().length();i++)text.append(i+1).append(". ").append(e.waypoints().optJSONObject(i).optString("name")).append('\n');}text.append(String.format(Locale.US,"\nApprove adds %.1f reconstructed km to Total. GPS fixes and current-drive metrics stay separate. Load/unload affects map visibility only.",total/1000));
  new AppDialogs(activity).setTitle("Review reconstructed road routes").setMessage(text.toString()).setPositiveButton("Approve merge",(d,w)->worker.execute(()->{try{List<Entry> next=new ArrayList<>(entries);for(Entry e:batch){next.removeIf(old->old.id().equals(e.id()));next.add(e);}persist(next);drafts=List.of();post(changed);}catch(Exception e){post(()->message("Merge failed · existing trails retained",e.getMessage()));}})).setNeutralButton("View on map",(d,w)->{changed.run();List<RoutePlan.Point> points=new ArrayList<>();for(Entry e:batch)points.addAll(e.points());preview.accept(points);Toast.makeText(activity,"Preview only · menu → Historical trails → Review pending previews to approve",Toast.LENGTH_LONG).show();}).setNegativeButton("Edit / discard",(d,w)->{String[] names=batch.stream().map(Entry::title).toArray(String[]::new);new AppDialogs(activity).setItems(names,(x,index)->{Entry e=batch.get(index);new AppDialogs(activity).setTitle(e.title()).setPositiveButton("Edit",(z,b)->edit(e.id(),e.title(),e.raw(),e.uri())).setNegativeButton("Discard preview",(z,b)->{List<Entry> next=new ArrayList<>(drafts);next.removeIf(old->old.id().equals(e.id()));drafts=List.copyOf(next);changed.run();}).show();}).setNegativeButton("Close",null).show();}).show();
 }
 private void saveReplacement(Entry e){worker.execute(()->{try{List<Entry> next=new ArrayList<>(entries);for(int i=0;i<next.size();i++)if(next.get(i).id().equals(e.id()))next.set(i,e);persist(next);post(changed);}catch(Exception x){post(()->message("Cannot save",x.getMessage()));}});}
 private void persist(List<Entry> next)throws Exception{if(loadError)throw new IOException("Existing historical journal could not be read; restore it before making changes");JSONArray array=new JSONArray();for(Entry e:next)array.put(encode(e));byte[] data=new JSONObject().put("schema",1).put("trails",array).toString().getBytes(StandardCharsets.UTF_8);if(data.length>24000000)throw new IOException("Historical journal exceeds 24 MB; split or simplify lists");FileOutputStream out=file.startWrite();try{out.write(data);file.finishWrite(out);}catch(Exception e){file.failWrite(out);throw e;}entries=List.copyOf(next);}
 static JSONObject encode(Entry e)throws Exception{JSONArray points=new JSONArray();for(RoutePlan.Point p:e.points())points.put(new JSONArray().put(p.lat()).put(p.lon()));return new JSONObject().put("id",e.id()).put("title",e.title()).put("raw",e.raw()).put("uri",e.uri()).put("visible",e.visible()).put("created",e.created()).put("meters",e.meters()).put("points",points).put("waypoints",e.waypoints()).put("source","user_reconstructed_road_route");}
 static Entry decode(JSONObject e)throws Exception{List<RoutePlan.Point> points=new ArrayList<>();JSONArray rows=e.getJSONArray("points");if(rows.length()>200000)throw new IOException("Too many points");for(int i=0;i<rows.length();i++){JSONArray p=rows.getJSONArray(i);points.add(new RoutePlan.Point(p.getDouble(0),p.getDouble(1)));}double meters=e.getDouble("meters");if(!Double.isFinite(meters)||meters<0||points.size()<2)throw new IOException("Invalid historical route");return new Entry(e.getString("id"),e.getString("title"),e.getString("raw"),e.optString("uri"),e.optBoolean("visible",true),e.getLong("created"),meters,List.copyOf(points),e.getJSONArray("waypoints"));}
 private static String read(InputStream source,int limit)throws Exception{if(source==null)throw new IOException("File not available");try(InputStream in=source;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("File exceeds size limit");out.write(b,0,n);}return out.toString("UTF-8");}}
 static String backupJson(android.content.Context context)throws Exception{File f=new File(context.getFilesDir(),"historical-trails-v1.json");return f.exists()?read(new AtomicFile(f).openRead(),24000000):"";}
 static void validateBackup(String raw)throws Exception{if(raw.isBlank())return;JSONObject root=new JSONObject(raw);if(root.getInt("schema")!=1)throw new IOException("Unsupported historical schema");JSONArray a=root.getJSONArray("trails");for(int i=0;i<a.length();i++)decode(a.getJSONObject(i));}
 static synchronized void restoreMerged(android.content.Context context,String raw)throws Exception{if(raw==null||raw.isBlank())return;validateBackup(raw);LinkedHashMap<String,JSONObject> all=new LinkedHashMap<>();String old=backupJson(context);if(!old.isBlank()){JSONArray a=new JSONObject(old).getJSONArray("trails");for(int i=0;i<a.length();i++){JSONObject e=a.getJSONObject(i);all.put(e.getString("id"),e);}}JSONArray a=new JSONObject(raw).getJSONArray("trails");for(int i=0;i<a.length();i++){JSONObject e=a.getJSONObject(i);JSONObject previous=all.get(e.getString("id"));if(previous==null||e.getLong("created")>previous.getLong("created"))all.put(e.getString("id"),e);}JSONArray merged=new JSONArray();for(JSONObject e:all.values())merged.put(e);AtomicFile file=new AtomicFile(new File(context.getFilesDir(),"historical-trails-v1.json"));FileOutputStream out=file.startWrite();try{out.write(new JSONObject().put("schema",1).put("trails",merged).toString().getBytes(StandardCharsets.UTF_8));file.finishWrite(out);}catch(Exception e){file.failWrite(out);throw e;}}
 void reload(){worker.execute(()->{try{String raw=backupJson(activity);List<Entry> loaded=new ArrayList<>();if(!raw.isBlank()){JSONArray rows=new JSONObject(raw).getJSONArray("trails");for(int i=0;i<rows.length();i++)loaded.add(decode(rows.getJSONObject(i)));}entries=List.copyOf(loaded);loadError=false;post(changed);}catch(Exception e){loadError=true;post(()->message("Cannot reload historical trails",e.getMessage()));}});}
 public void close(){closed=true;worker.shutdownNow();}
}
